/* @layer shared-asset-extraction @kind logic */
import type { ImportContext } from '../pipeline/import-context.type';
import { wramOf } from '../recipes/wram-of';
import { peekOracleless } from './shared/state-recipe';
import type { GenFiles } from './oracle-gen-stage';
import { hexByte } from './c-text';

const HEAD = [
  '// GENERATED by tools/gen/ct_charbase.py -- do not edit. The 8 CT character records copied to',
  '// $7E:2600 by the new-game init (ROM C2/956E). Base 0x00-0x35/0x41-0x4F = ROM $CC:0000; the',
  '// DERIVED block 0x36-0x40 (0x3D ATK / 0x3E DEF, recomputed from gear -- 0xFF in the ROM base)',
  "// = the oracle's post-recalc values (gato_t0 $2600). Extracted once so the runtime needs only",
  '// ct_assets.dat. Layout: +3 curHP,+5 maxHP,+7/+9 MP,+0B..11 stats,+12 LV,+13 XP,+27 helm,',
  '// +28 armor,+29 weapon,+2A accessory,+2B NEXT,+3D ATK,+3E DEF.',
  '#ifndef CT_CHARBASE_H\n#define CT_CHARBASE_H\n#include <stdint.h>',
  '#define CT_CHARBASE_STRIDE 0x50\n#define CT_CHARBASE_COUNT 8',
  'static const uint8_t ctCharBase[0x280] = {',
];

/** tools/gen/ct_charbase.py: the 8 character records of the new-game init, ROM base plus the derived block from recipe gato_wait. */
const genCtCharbase = async (ctx: ImportContext): Promise<GenFiles> => {
  const gato = wramOf(await peekOracleless(ctx, 'gato_wait'));
  const rec = ctx.rom.slice(0xc0000, 0xc0280);
  for (let cid = 0; cid < 8; cid += 1) {
    const b = cid * 0x50;
    rec.set(gato.subarray(0x2600 + b + 0x36, 0x2600 + b + 0x41), b + 0x36);
  }
  const rows: string[] = [];
  for (let i = 0; i < 0x280; i += 16) rows.push(`  ${Array.from(rec.subarray(i, i + 16), hexByte).join(',')},`);
  return { 'ct_charbase.h': `${HEAD.join('\n')}\n${rows.join('\n')}\n};\n#endif\n` };
};

export { genCtCharbase };
